class Solution:

	def minimumCost(self, cost, n, W):

		def go(ind, currw):
			if currw > W:
				return 10 ** 18
			if ind == n:
				if currw == W:
					return 0
				return 10 ** 18
			if dp[ind][currw] != -1:
				return dp[ind][currw]
			c1 = 10 ** 18
			if cost[ind] != -1:
				c1 = cost[ind] + go(ind, currw + ind + 1)
			c2 = go(ind + 1, currw)
			ans = min(c1, c2)
			dp[ind][currw] = ans
			return ans
		dp = []
		for i in range(n):
			x = []
			for j in range(W + 1):
				x.append(-1)
			dp.append(x)
		ans1 = go(0, 0)
		if ans1 == 10 ** 18:
			return -1
		return ans1
